import Item from '../components/Item';

// in render method, replace <Text> with the following
<FlatList
  data={this.state.mockItems}
  contentContainerStyle={styles.content}
  renderItem={row => {
    return <Item text={row.item} />;
  }}
  keyExtractor={item => item.id}
/>;
```

